<script setup lang="ts">
import { computed, ref } from 'vue'
import { dashboardLights } from '../content'
import type { DashboardLight } from '../types'
const query = ref(''); const selected = ref<DashboardLight | null>(null); const severity = ref('all')
const filtered = computed(() => dashboardLights.filter(light => (severity.value === 'all' || light.severity === severity.value) && `${light.name} ${light.english}`.toLowerCase().includes(query.value.toLowerCase())))
</script>
<template><div class="lights-view"><p class="muted">Chạm vào biểu tượng đang sáng trên táp-lô để biết việc cần làm.</p><input v-model="query" class="search" type="search" placeholder="⌕  Tìm đèn: phanh, động cơ..." /><div class="filters"><button v-for="item in [['all','Tất cả'],['critical','Khẩn cấp'],['warn','Cảnh báo'],['info','Theo dõi']]" :key="item[0]" :class="{ selected: severity === item[0] }" @click="severity = item[0]">{{ item[1] }}</button></div><div class="light-grid"><button v-for="light in filtered" :key="light.id" class="light-card" @click="selected = light"><span class="light-symbol" :class="light.severity">{{ light.icon }}</span><strong>{{ light.name }}</strong><small>{{ light.english }}</small><span class="severity-label" :class="light.severity">{{ light.severity === 'critical' ? 'Dừng xe' : light.severity === 'warn' ? 'Kiểm tra sớm' : 'Theo dõi' }}</span></button></div><div v-if="selected" class="modal-backdrop" @click.self="selected = null"><article class="light-detail"><button class="close" aria-label="Đóng" @click="selected = null">×</button><span class="light-symbol large" :class="selected.severity">{{ selected.icon }}</span><p class="eyebrow">{{ selected.english.toUpperCase() }}</p><h2>{{ selected.name }}</h2><p>{{ selected.description }}</p><h3>Việc cần làm ngay</h3><ol><li v-for="action in selected.actions" :key="action">{{ action }}</li></ol><div class="safety"><strong>Không nên</strong><p>{{ selected.avoid }}</p></div></article></div></div></template>
